.chat-messages-area,
.chat-message-list-custom {
  padding-top: calc(env(safe-area-inset-top, 14px) + var(--header-card-height) + 12px) !important;
  padding-bottom: var(--list-bottom-clearance) !important;
  box-sizing: border-box !important;

  /* 👇 顶底双向渐变遮罩：顶部淡入 + 中间实色 + 底部在胶囊上方自然淡出 */
  -webkit-mask-image: linear-gradient(
    to bottom,
    transparent 0px,
    black calc(env(safe-area-inset-top, 20px) + 35px),
    black calc(100% - 90px),
    transparent calc(100% - 1px)
  ) !important;
  mask-image: linear-gradient(
    to bottom,
    transparent 0px,
    black calc(env(safe-area-inset-top, 20px) + 35px),
    black calc(100% - 90px),
    transparent calc(100% - 1px)
  ) !important;
}

.chat-detail-screen::before {
  display: none !important;
}

.msg-bubble-wrapper[data-absolute-last="true"],
.msg-bubble-wrapper:last-child {
  margin-bottom: 5px !important;
}

/* =========================================================
   2.1 【超细实心锁·单行 Encrypted 时间戳】
   ========================================================= */
.timestamp-custom {
