.msg-bubble-wrapper:has([class*="dot"]) .bubble-them-custom::after {
  display: none !important;
  content: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
}

/* 👇【核心修复】彻底灭杀我方/对方所有卡片上的小尾巴（含视频/通话卡片） */
.bubble-me-custom:has(.msg-transfer-card)::before,
.bubble-me-custom:has(.msg-transfer-card)::after,
.bubble-me-custom:has(.msg-redpacket-card)::before,
.bubble-me-custom:has(.msg-redpacket-card)::after,
