/* =================================== */
/* 语音气泡 */
/* =================================== */
:root{
  --voice-bubble-width:80px;
  --voice-fake-time:"13\"";
  --voice-icon-size:19px;
  --voice-text-size:12px;
  --voice-me-icon-x:5px;
  --voice-me-icon-y:0px;
  --voice-me-text-x:6px;
  --voice-me-text-y:0px;
  --voice-them-icon-x:-4px;
  --voice-them-icon-y:0px;
  --voice-them-text-x:-8px;
  --voice-them-text-y:0px;
  --voice-dl-offset:-35px;
}
.bubble-me-custom:has(.voice-msg),
.bubble-them-custom:has(.voice-msg){
  background:transparent!important;
  box-shadow:none!important;
  border:none!important;
  padding:0!important;
}
.bubble-me-custom:has(.voice-msg)::before,
.bubble-them-custom:has(.voice-msg)::before{display:none!important;}
.voice-msg{
  display:flex!important;
  flex-direction:column!important;
  width:fit-content!important;
  max-width:100%!important;
  min-width:0!important;
  padding:0!important;
  margin:0!important;
  position:relative!important;
  overflow:visible!important;
}
.voice-msg-me{align-items:flex-end!important;}
.voice-msg-them{align-items:flex-start!important;}
.voice-controls-row{
  width:var(--voice-bubble-width)!important;
  height:36px!important;
  border-radius:var(--wechat-bubble-radius)!important;
  position:relative!important;
  display:flex!important;
  align-items:center!important;
  padding:0!important;
  margin:0!important;
}
.voice-msg-me .voice-controls-row{background-color:var(--bubble-me-bg)!important;}
.voice-msg-them .voice-controls-row{background-color:var(--bubble-them-bg)!important;}
.voice-msg-me .voice-controls-row::before{
  content:""!important;
  display:block!important;
  position:absolute!important;
  top:var(--bubble-tail-top)!important;
  right:var(--bubble-me-tail-right)!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background-color:var(--bubble-me-bg)!important;
  pointer-events:none!important;
  border-radius: 2px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important;
}
.voice-msg-them .voice-controls-row::before{
  content:""!important;
  display:block!important;
  position:absolute!important;
  top:var(--bubble-tail-top)!important;
  left:var(--bubble-them-tail-left)!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background-color:var(--bubble-them-bg)!important;
  pointer-events:none!important;
  border-radius: 2px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important;
}
.voice-waveform,.voice-duration{display:none!important;}
.voice-play-btn{
  width:100%!important;
  height:100%!important;
  display:flex!important;
  align-items:center!important;
  background:transparent!important;
  border:none!important;
  padding:0 12px!important;
  box-sizing:border-box!important;
  position:relative!important;
}
.voice-msg-me .voice-play-btn{justify-content:flex-end!important;}
.voice-msg-them .voice-play-btn{justify-content:flex-start!important;}
.voice-msg-me .voice-play-btn::before{
  content:var(--voice-fake-time);
  font-size:var(--voice-text-size)!important;
  color:var(--bubble-me-color)!important;
  margin-right:6px!important;
  transform:translate(var(--voice-me-text-x),var(--voice-me-text-y))!important;
}
.voice-msg-me .voice-play-btn::after{
  content:"";
  display:block;
  width:var(--voice-icon-size)!important;
  height:var(--voice-icon-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/623bc1a2-ed39-4ad7-bb3e-6470eb61ad60.png');
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  transform:translate(var(--voice-me-icon-x),var(--voice-me-icon-y))!important;
}
.voice-msg-them .voice-play-btn::before{
  content:"";
  display:block;
  width:var(--voice-icon-size)!important;
  height:var(--voice-icon-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/623bc1a2-ed39-4ad7-bb3e-6470eb61ad60.png');
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  transform:translate(var(--voice-them-icon-x),var(--voice-them-icon-y)) scaleX(-1)!important;
}
.voice-msg-them .voice-play-btn::after{
  content:var(--voice-fake-time);
  font-size:var(--voice-text-size)!important;
  color:var(--bubble-them-color)!important;
  margin-left:6px!important;
  transform:translate(var(--voice-them-text-x),var(--voice-them-text-y))!important;
}
@media (prefers-color-scheme: dark) {
  body .voice-msg-them .voice-play-btn::before{
    filter:invert(1) opacity(var(--dark-icon-opacity,.8))!important;
  }
}
.voice-play-btn svg{
  display:block!important;
  position:absolute!important;
  top:50%!important;
  transform:translateY(-50%)!important;
  width:30px!important;
  height:100%!important;
  opacity:0!important;
  z-index:10!important;
}
.voice-msg-me .voice-play-btn svg{right:0!important;left:auto!important;}
.voice-msg-them .voice-play-btn svg{left:0!important;right:auto!important;}
.voice-download-btn{
  display:flex!important;
  opacity:0!important;
  position:absolute!important;
  top:50%!important;
  transform:translateY(-50%)!important;
  width:30px!important;
  height:30px!important;
  z-index:5!important;
}
.voice-msg-me .voice-download-btn{left:var(--voice-dl-offset)!important;}
.voice-msg-them .voice-download-btn{right:var(--voice-dl-offset)!important;}
.voice-transcription-toggle{
  display:block!important;
  position:absolute!important;
  top:0!important;
  left:0!important;
  width:100%!important;
  height:40px!important;
  opacity:0!important;
  z-index:5!important;
  margin:0!important;
  padding:0!important;
}
.voice-transcription{
  display:block!important;
  position:relative!important;
  top:auto!important;
  left:auto!important;
  right:auto!important;
  margin-top:-2px!important;
  width:fit-content!important;
  max-width:72vw!important;
  background:#FFFFFF!important;
  border-radius:5px!important;
  padding:9px 11px!important;
  color:#000000!important;
  font-size: 15px !important;
  line-height:1.2!important;
  white-space:pre-wrap!important;
  word-wrap:break-word!important;
  word-break:break-all!important;
  box-shadow: none !important;
  z-index:20!important;
  animation:none!important;
}
@media (prefers-color-scheme: dark) {
  body .voice-transcription{
    background:#2C2C2C!important;
    color:#FFFFFF!important;
    border:1px solid none !important;
  }
}
.voice-controls-row .voice-retry-btn,
.voice-controls-row .voice-error-btn,
.voice-controls-row button:not(.voice-play-btn):not(.voice-download-btn){
  display:none!important;
  opacity:0!important;
  pointer-events:none!important;
}

/* =================================== */
/* 终极防白线 */
/* =================================== */
@media (prefers-color-scheme: dark){
  .input-area-custom,
  .input-action-bar-custom{
    backdrop-filter:none!important;
    -webkit-backdrop-filter:none!important;
    box-shadow:none!important;
    outline:none!important;
    border-top:0!important;
    border-top-color:transparent!important;
  }
  .input-area-custom{
    position:relative!important;
    background-color:#1E1E1E!important;
    background-image:linear-gradient(#1E1E1E,#1E1E1E)!important;
    z-index:999!important;
  }
  .input-area-custom::after{
    content:""!important;
    position:absolute!important;
    top:-1px!important;
    left:0!important;
    right:0!important;
    height:3px!important;
    background-color:#1E1E1E!important;
    background-image:linear-gradient(#1E1E1E,#1E1E1E)!important;
    border:none!important;
    box-shadow:none!important;
    z-index:9999!important;
    pointer-events:none!important;
  }
}

/* =================================== */
/* 🌟 时间戳与拍一拍胶囊 */
/* =================================== */
:root {
  --sys-msg-bg: rgba(239, 239, 239, 0.85);
  --sys-msg-color: #888888;
  --sys-msg-radius: 5px;
  --sys-msg-padding: 4px 8px;
  --sys-msg-font-size: 12px;
  --sys-msg-backdrop: blur(10px) saturate(180%);
}
@media (prefers-color-scheme: dark) {
  body {
    --sys-msg-bg: rgba(37, 37, 37, 0.85);
    --sys-msg-color: #999999;
  }
}
.timestamp-custom,
.date-divider-custom {
  display: block !important;
  width: fit-content !important;
  margin: 12px auto !important;
  padding: var(--sys-msg-padding) !important;
  background: var(--sys-msg-bg) !important;
  color: var(--sys-msg-color) !important;
  border-radius: var(--sys-msg-radius) !important;
  font-size: var(--sys-msg-font-size) !important;
  font-weight: 500 !important;
  backdrop-filter: var(--sys-msg-backdrop) !important;
  -webkit-backdrop-filter: var(--sys-msg-backdrop) !important;
  border: none !important;
  box-shadow: none !important;
}
.nuo-pat-msg {
  display: block !important;
  width: fit-content !important;
  margin: 12px auto !important;
  padding: var(--sys-msg-padding) !important;
  background: var(--sys-msg-bg) !important;
  color: var(--sys-msg-color) !important;
  border-radius: var(--sys-msg-radius) !important;
  font-size: var(--sys-msg-font-size) !important;
  backdrop-filter: var(--sys-msg-backdrop) !important;
  -webkit-backdrop-filter: var(--sys-msg-backdrop) !important;
  border: none !important;
  box-shadow: none !important;
  font-style: normal !important;
}

/* =================================== */
/* 🌟 翻译微信化 */
/* =================================== */
.msg-translation-detached {
  display: block !important;
  margin-top: 5px !important;
  width: fit-content !important;
  max-width: 72vw !important;
}
.msg-translation-content {
  display: none !important;
}
.msg-translation-detached-content {
  background: #FFFFFF !important;
  color: #000000 !important;
  border-radius: 5px !important;
  padding: 10px 12px !important;
  font-size: 14px !important;
  line-height: 1.5 !important;
  box-shadow: none !important;
  word-wrap: break-word !important;
  word-break: break-all !important;
}
@media (prefers-color-scheme: dark) {
  body .msg-translation-detached-content {
    background: #2C2C2C !important;
    color: #FFFFFF !important;
    border: 1px solid none !important;
  }
}
.msg-translation-wrapper {
  position: absolute !important;
  top: 0 !important;
  right: 0 !important;
  width: 45px !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
}
.msg-translation-btn {
  width: 100% !important;
  height: 100% !important;
  opacity: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}
.bubble-me-custom,
.bubble-them-custom {
  position: relative !important;
}

/* 🌟 翻译小尾巴 */
.msg-translation-detached-content {
  padding-bottom: 25px !important;
  position: relative !important;
}
.msg-translation-detached-content::after {
  content: "由微信提供翻译支持";
  position: absolute !important;
  left: 28px !important;
  bottom: 10px !important;
  font-size: 11px !important;
  color: #b2b2b2 !important;
  line-height: 12px !important;
  pointer-events: none !important;
}
.msg-translation-detached-content::before {
  content: "";
  position: absolute !important;
  left: 12px !important;
  bottom: 10px !important;
  width: 12px !important;
  height: 12px !important;
  background-color: #c9c9c9 !important;
  border-radius: 50% !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" stroke="%23F5F5F5" stroke-linecap="round"><line x1="6" y1="13" x2="10" y2="17" stroke-width="2.5"/><line x1="10" y1="17" x2="18" y2="8" stroke-width="1.5"/></svg>') !important;
  background-size: 12px 12px !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  pointer-events: none !important;
}
/* 给独立翻译气泡加个“保底宽度”，防止短句把底部小字挤换行 */
.msg-translation-detached,
.msg-translation-detached-content {
  min-width: 140px !important;
}

/* 顺手给底部小字加个不换行保护 */
.msg-translation-detached-content::after {
  white-space: nowrap !important;
}
@media (prefers-color-scheme: dark) {
  body .msg-translation-detached-content::after {
    color: #8e8e93 !important;
  }
  body .msg-translation-detached-content::before {
    background-color: #bcbcbc !important;
  }
}

/* =================================== */
/*  🍓转账卡片 by小Q怡 */
/* =================================== */
:root{
  --transfer-card-bg:#FA9D3B;
  --transfer-card-bg-received:#FCE2BC;
  --transfer-card-bg-expired:#E6C7A5;
  --transfer-icon-default:url('https://i.postimg.cc/j5CqLH5J/wu-biao-ti38-20260205143013.png');
  --transfer-icon-received:url('https://nos.netease.com/ysf/032ae26e2e69a232d3bb904047b34e38.png');
  --transfer-icon-returned:url('https://nos.netease.com/ysf/0b5a28d77f1934fdcc6750fd8f9897c6.png');
  --transfer-icon-expired:url('https://nos.netease.com/ysf/dfbb30c0b7383f9209c03597b101adfe.png');
  --transfer-me-remark:"你发起了一笔转账";
  --transfer-them-remark:"请收款";
  --transfer-status-text:"微信转账";
  --amount-top:14px;
  --amount-left:68px;
  --amount-font-size:20px;
  --amount-letter-spacing:-1.2px;
  --remark-top:40px;
  --remark-left:68px;
  --expire-display:block;
}
.msg-transfer-card{
  position:relative!important;
  width:264px!important;
  height:96px!important;
  margin:0 auto!important;
  padding:0!important;
  border:none!important;
  border-radius:4px!important;
  background:var(--transfer-card-bg)!important;
  overflow:visible!important;
  box-shadow:none!important;
  transition:background-color .25s ease!important;
}
.msg-transfer-card .msg-transfer-icon svg,
.msg-transfer-card .msg-transfer-icon img,
.msg-transfer-card .msg-transfer-label,
.msg-transfer-card .msg-transfer-subtitle,
.msg-transfer-card .msg-transfer-divider,
.msg-transfer-card .msg-transfer-footer,
.msg-transfer-card .msg-transfer-status-text,
.msg-transfer-card .msg-transfer-chevron,
.msg-transfer-card .msg-transfer-check,
.msg-transfer-card .msg-transfer-dot,
.msg-transfer-card .msg-transfer-header > svg,
.msg-transfer-card .msg-transfer-content > svg{display:none!important;}
.msg-transfer-card .msg-transfer-content{
  position:relative!important;
  width:100%!important;
  height:100%!important;
}
.msg-transfer-card .msg-transfer-header{
  position:static!important;
  display:block!important;
}
.msg-transfer-card .msg-transfer-icon{
  position:absolute!important;
  top:12px!important;
  left:12px!important;
  width:44px!important;
  height:44px!important;
  display:block!important;
  background-image:var(--transfer-icon-default)!important;
  background-size:contain!important;
  background-repeat:no-repeat!important;
  background-position:center!important;
  background-color:transparent!important;
  font-size:0!important;
  color:transparent!important;
  z-index:3!important;
  opacity:1!important;
  visibility:visible!important;
}
.msg-transfer-card .msg-transfer-amount-section{
  position:absolute!important;
  top:var(--amount-top)!important;
  left:var(--amount-left)!important;
  right:12px!important;
  display:block!important;
  font-size:0!important;
  line-height:1!important;
  z-index:5!important;
}
.msg-transfer-card .msg-transfer-amount{
  display:block!important;
  margin:0!important;
  padding:0!important;
  font-size:var(--amount-font-size)!important;
  font-weight:700!important;
  line-height:1!important;
  color:#ffffff!important;
  -webkit-text-fill-color:#ffffff!important;
  letter-spacing:var(--amount-letter-spacing)!important;
  white-space:nowrap!important;
  overflow:visible!important;
  text-align:left!important;
  font-variant-numeric:tabular-nums!important;
}
.msg-transfer-card .msg-transfer-amount span,
.msg-transfer-card .msg-transfer-amount *{
  display:inline!important;
  writing-mode:horizontal-tb!important;
  font-size:var(--amount-font-size)!important;
  font-weight:700!important;
  color:#ffffff!important;
  -webkit-text-fill-color:#ffffff!important;
  white-space:nowrap!important;
  letter-spacing:var(--amount-letter-spacing)!important;
  word-spacing:-3px!important;
}
.msg-transfer-card .msg-transfer-content::after{
  position:absolute!important;
  top:var(--remark-top)!important;
  left:var(--remark-left)!important;
  right:12px!important;
  font-size:12px!important;
  font-weight:400!important;
  line-height:1.2!important;
  color:rgba(255,255,255,.92)!important;
  -webkit-text-fill-color:rgba(255,255,255,.92)!important;
  white-space:nowrap!important;
  overflow:hidden!important;
  text-overflow:ellipsis!important;
  z-index:10!important;
}
.msg-transfer-card::before{
  content:var(--transfer-status-text)!important;
  position:absolute!important;
  left:12px!important;
  bottom:8px!important;
  font-size:11px!important;
  font-weight:600!important;
  line-height:1!important;
  color:rgba(255,255,255,.82)!important;
  -webkit-text-fill-color:rgba(255,255,255,.82)!important;
  z-index:5!important;
}
.msg-transfer-card .msg-transfer-expiry{
  display:var(--expire-display)!important;
  position:absolute!important;
  right:12px!important;
  bottom:8px!important;
  left:auto!important;
  top:auto!important;
  margin:0!important;
  padding:0!important;
  font-size:10px!important;
  font-weight:400!important;
  line-height:1!important;
  text-align:right!important;
  color:rgba(255,255,255,.75)!important;
  -webkit-text-fill-color:rgba(255,255,255,.75)!important;
  background:transparent!important;
  z-index:6!important;
  opacity:1!important;
  visibility:visible!important;
}
.msg-me .msg-transfer-card,
.msg-them .msg-transfer-card,
.bubble-me-custom .msg-transfer-card,
.bubble-them-custom .msg-transfer-card{background:var(--transfer-card-bg)!important;}
.msg-me .msg-transfer-card .msg-transfer-icon,
.msg-them .msg-transfer-card .msg-transfer-icon,
.bubble-me-custom .msg-transfer-card .msg-transfer-icon,
.bubble-them-custom .msg-transfer-card .msg-transfer-icon{background-image:var(--transfer-icon-default)!important;}
.msg-me .msg-transfer-card .msg-transfer-content::after,
.bubble-me-custom .msg-transfer-card .msg-transfer-content::after{content:var(--transfer-me-remark)!important;}
.msg-them .msg-transfer-card .msg-transfer-content::after,
.bubble-them-custom .msg-transfer-card .msg-transfer-content::after{content:var(--transfer-them-remark)!important;}
.msg-me .msg-transfer-card.msg-transfer-success,
.msg-them .msg-transfer-card.msg-transfer-success,
.bubble-me-custom .msg-transfer-card.msg-transfer-success,
.bubble-them-custom .msg-transfer-card.msg-transfer-success{
  background:var(--transfer-card-bg-received)!important;
  background-color:var(--transfer-card-bg-received)!important;
}
.msg-transfer-card.msg-transfer-success .msg-transfer-icon{background-image:var(--transfer-icon-received)!important;}
.msg-me .msg-transfer-card.msg-transfer-success .msg-transfer-content::after,
.bubble-me-custom .msg-transfer-card.msg-transfer-success .msg-transfer-content::after{content:"已收款"!important;}
.msg-them .msg-transfer-card.msg-transfer-success .msg-transfer-content::after,
.bubble-them-custom .msg-transfer-card.msg-transfer-success .msg-transfer-content::after{content:"已被接受"!important;}
.msg-me .msg-transfer-card.msg-transfer-rejected,
.msg-them .msg-transfer-card.msg-transfer-rejected,
.bubble-me-custom .msg-transfer-card.msg-transfer-rejected,
.bubble-them-custom .msg-transfer-card.msg-transfer-rejected{
  background:var(--transfer-card-bg-received)!important;
  background-color:var(--transfer-card-bg-received)!important;
}
.msg-transfer-card.msg-transfer-rejected .msg-transfer-icon{background-image:var(--transfer-icon-returned)!important;}
.msg-me .msg-transfer-card.msg-transfer-rejected .msg-transfer-content::after,
.bubble-me-custom .msg-transfer-card.msg-transfer-rejected .msg-transfer-content::after{content:"已被退还"!important;}
.msg-them .msg-transfer-card.msg-transfer-rejected .msg-transfer-content::after,
.bubble-them-custom .msg-transfer-card.msg-transfer-rejected .msg-transfer-content::after{content:"已退还"!important;}
.msg-me .msg-transfer-card.msg-transfer-expired-card,
.msg-them .msg-transfer-card.msg-transfer-expired-card,
.bubble-me-custom .msg-transfer-card.msg-transfer-expired-card,
.bubble-them-custom .msg-transfer-card.msg-transfer-expired-card{
  background:var(--transfer-card-bg-expired)!important;
  background-color:var(--transfer-card-bg-expired)!important;
}
.msg-transfer-card.msg-transfer-expired-card .msg-transfer-icon{background-image:var(--transfer-icon-expired)!important;}
.msg-me .msg-transfer-card.msg-transfer-expired-card .msg-transfer-content::after,
.bubble-me-custom .msg-transfer-card.msg-transfer-expired-card .msg-transfer-content::after{content:"已过期"!important;}
.msg-them .msg-transfer-card.msg-transfer-expired-card .msg-transfer-content::after,
.bubble-them-custom .msg-transfer-card.msg-transfer-expired-card .msg-transfer-content::after{content:"已过期"!important;}
.msg-transfer-card.msg-transfer-expired-card .msg-transfer-expiry{display:none!important;}
.msg-me .msg-transfer-card::after,
.bubble-me-custom .msg-transfer-card::after,
.msg-them .msg-transfer-card::after,
.bubble-them-custom .msg-transfer-card::after{
  content:""!important;
  display:block!important;
  position:absolute!important;
  top:var(--bubble-tail-top)!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  border-radius: 2px !important;
  transform:rotate(45deg)!important;
  z-index:-1!important;
  pointer-events:none!important;
  background:var(--transfer-card-bg)!important;
}
.msg-me .msg-transfer-card::after,
.bubble-me-custom .msg-transfer-card::after{
  right:var(--bubble-me-tail-right)!important;
  left:auto!important;
}
.msg-them .msg-transfer-card::after,
.bubble-them-custom .msg-transfer-card::after{
  left:var(--bubble-them-tail-left)!important;
  right:auto!important;
}
.msg-me .msg-transfer-card.msg-transfer-success::after,
.msg-them .msg-transfer-card.msg-transfer-success::after,
.bubble-me-custom .msg-transfer-card.msg-transfer-success::after,
.bubble-them-custom .msg-transfer-card.msg-transfer-success::after,
.msg-me .msg-transfer-card.msg-transfer-rejected::after,
.msg-them .msg-transfer-card.msg-transfer-rejected::after,
.bubble-me-custom .msg-transfer-card.msg-transfer-rejected::after,
.bubble-them-custom .msg-transfer-card.msg-transfer-rejected::after{background:var(--transfer-card-bg-received)!important;}
.msg-me .msg-transfer-card.msg-transfer-expired-card::after,
.msg-them .msg-transfer-card.msg-transfer-expired-card::after,
.bubble-me-custom .msg-transfer-card.msg-transfer-expired-card::after,
.bubble-them-custom .msg-transfer-card.msg-transfer-expired-card::after{background:var(--transfer-card-bg-expired)!important;}
.bubble-me-custom:has(.msg-transfer-card)::before,
.bubble-them-custom:has(.msg-transfer-card)::before{display:none!important;}

