    position: absolute !important;
    top: 0;
    width: 100%;
    z-index: 100;
}
/* 顶栏 */
.glass-header {
    position: relative;
    box-shadow: none;
    padding-top: 46px !important;
    padding-bottom: 1px !important;
    backdrop-filter: blur(30px) saturate(180%) !important; /* 加强磨砂感 */
    -webkit-backdrop-filter: blur(30px) saturate(180%) !important;
    border-bottom: var(--chat-header-border) !important;
}
.nuo-chat-header-unread-dot {
    display: none;
}

/* 动态改变颜色的未读胶囊 */
.nuo-chat-header-unread-num {
    height: 20px !important;
    min-width: 20px !important;
    margin-top: 15px;
    margin-left: -8px;
