/* ✅ 气泡去除包裹效果（核心：精确过滤隐藏引用块里的图片，恢复表情包去气泡功能） */
:is(.bubble-me-custom, .bubble-them-custom):has(:is( .msg-transfer-card, .msg-redpacket-card, .msg-videocall-card, .msg-loc-card, .msg-sim-card,  .gift-ig-container, .msg-image-wrapper, .msg-image-card, img:not(.msg-reply-block img, .msg-reply-block-detached img))) {
   filter: none !important;
   background: transparent !important;
   border: none !important;
   box-shadow: none !important;
   padding: 0 !important; /* 解除包裹的关键 */
}

/* 去掉气泡原本的尖角指针 */
.bubble-me-custom::after {
    content: "";
    position: absolute;
    top: 15px;
    right: -3.5px;
    width: 8px;
    height: 8px;
    border-radius: 1.2px;
    background: var(--bubble-me-bg);
    transform: rotate(45deg);
}
.bubble-them-custom::after {
    content: "";
    position: absolute;
    top: 15px;
    left: -3.5px;
    width: 8px;
    height: 8px;
    border-radius: 1.2px;
    background: var(--bubble-them-bg);
    transform: rotate(45deg);
}

/* 同样精确排除，防止尖角丢失 */
:is(.bubble-me-custom, .bubble-them-custom):has(:is( .msg-transfer-card, .msg-redpacket-card, .msg-videocall-card, .msg-loc-card, .msg-sim-card,  .gift-ig-container, .msg-image-wrapper, .msg-image-card, img:not(.msg-reply-block img, .msg-reply-block-detached img)))::before,
:is(.bubble-me-custom, .bubble-them-custom):has(:is( .msg-transfer-card, .msg-redpacket-card, .msg-videocall-card, .msg-loc-card, .msg-sim-card,  .gift-ig-container, .msg-image-wrapper, .msg-image-card, img:not(.msg-reply-block img, .msg-reply-block-detached img)))::after {
    display: none !important;
}

